const defaults = {name:'Alex Morgan',headline:'A curious developer, building things for the web.',bio:'I turn coffee into code and ideas into things you can click.\nAlways learning. Always building. A little better every day.',location:'Somewhere on Earth',website:'',working:'Something that makes the everyday a little easier',learning:'New ways to bring ideas to life',email:'',username:'',custom:'',tech:['JavaScript','React','Nodejs','TypeScript','Python','Git','Figma'],template:'essentials',sections:{about:true,stack:true,connect:true,stats:false,languages:false,streak:false,repos:false},repos:[]};
