const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=url=>{try{const u=new URL(url);return ['https:','http:','mailto:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const mdText=s=>String(s??'').replace(/([\\`*_{}\[\]<>#|])/g,'\\$1');
const mdURL=s=>encodeURI(String(s)).replace(/[()]/g,c=>'%'+c.charCodeAt(0).toString(16));
let toastTimer;
