function persist(){try{localStorage.setItem('readme-studio-v1',JSON.stringify(state));$('save-status').innerHTML='<i></i> Saved locally';}catch{$('save-status').textContent='Storage unavailable';}}
function badge(t){const [color,logo,logoColor]=techs[t];return `![${t}](https://img.shields.io/badge/${encodeURIComponent(t)}-${color}?style=flat&logo=${logo}&logoColor=${logoColor})`;}
function markdown(){
 if(state.sourceMode)return state.sourceMarkdown||'';
 const name=mdText(state.name||'Your name'),user=state.username.trim(),theme=state.template==='midnight'?'tokyonight':'transparent';
 let title=`# Hey there, I’m ${name} 👋`;
 if(state.template==='playful')title=`# Hello, curious human! I’m ${name} ✨`;
 if(state.template==='minimal')title=`# ${name}`;
 if(state.template==='terminal')title=`# $ whoami\n\n> ${name}`;
 if(state.template==='open-source')title=`# ${name} · Building in the open`;
 if(state.template==='midnight')title=`# ${name} / Building after hours 🌙`;
 let parts=[title];
 if(state.headline)parts.push(`### ${mdText(state.headline)}`);
 if(state.bio)parts.push(mdText(state.bio));
 if(state.sections.about){let lines=[];if(state.working)lines.push(`- 🔭 I’m currently working on **${mdText(state.working)}**`);if(state.learning)lines.push(`- 🌱 I’m currently learning **${mdText(state.learning)}**`);if(state.location)lines.push(`- 📍 Based in ${mdText(state.location)}`);if(lines.length)parts.push(lines.join('\n'));}
 if(state.sections.stack&&state.tech.length)parts.push(`## My toolkit\n\n${state.tech.map(badge).join(' ')}`);
 if(state.sections.connect){let links=[];if(user)links.push(`[GitHub](https://github.com/${encodeURIComponent(user)})`);if(state.website){const url=/^https?:\/\//i.test(state.website)?state.website:'https://'+state.website;if(safeURL(url)!=='#')links.push(`[Website](${mdURL(url)})`);}if(state.email)links.push(`[Email](mailto:${encodeURIComponent(state.email)})`);if(links.length)parts.push('## Let’s connect\n\n'+links.join(' · '));}
 if(state.sections.repos&&state.repos.length)parts.push('## A few things I’ve built\n\n'+state.repos.slice(0,4).map(r=>`- [${mdText(r.name)}](${mdURL(r.html_url)})${r.description?' — '+mdText(r.description):''}`).join('\n'));
 if(user){if(state.sections.stats)parts.push(`## GitHub at a glance\n\n![GitHub stats](https://github-readme-stats.vercel.app/api?username=${encodeURIComponent(user)}&show_icons=true&theme=${theme}&hide_border=true)`);if(state.sections.languages)parts.push(`![Top languages](https://github-readme-stats.vercel.app/api/top-langs/?username=${encodeURIComponent(user)}&layout=compact&theme=${theme}&hide_border=true)`);if(state.sections.streak)parts.push(`![Contribution streak](https://streak-stats.demolab.com?user=${encodeURIComponent(user)}&theme=${theme}&hide_border=true)`);}
 if(state.custom)parts.push(state.custom);
 return parts.join('\n\n')+'\n';
}
// Render a safe subset of Markdown; imported raw HTML is displayed as text.
function inline(text){
 const tokens=[];const token=html=>{tokens.push(html);return `\u0000${tokens.length-1}\u0000`;};
 let s=escapeHTML(text);
 s=s.replace(/!\[([^\]]*)\]\(([^\s)]+)\)/g,(_,alt,url)=>token(`<img alt="${alt}" src="${escapeHTML(safeURL(url.replace(/&amp;/g,'&')))}" loading="lazy" referrerpolicy="no-referrer">`));
 s=s.replace(/\[([^\]]+)\]\(([^\s)]+)\)/g,(_,label,url)=>token(`<a href="${escapeHTML(safeURL(url.replace(/&amp;/g,'&')))}" target="_blank" rel="noopener noreferrer">${label}</a>`));
 s=s.replace(/`([^`]+)`/g,(_,v)=>token(`<code>${v}</code>`)).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\\([\\`*_{}\[\]&lt;&gt;#|])/g,'$1');
 return s.replace(/\u0000(\d+)\u0000/g,(_,i)=>tokens[+i]);
}
function renderMarkdown(md){let html='',list=false,code=false,codeLines=[];for(const line of md.split('\n')){if(line.startsWith('```')){if(code){html+='<pre><code>'+escapeHTML(codeLines.join('\n'))+'</code></pre>';codeLines=[];}code=!code;continue;}if(code){codeLines.push(line);continue;}if(!line.startsWith('- ')&&list){html+='</ul>';list=false;}if(line.startsWith('- ')){if(!list){html+='<ul>';list=true;}html+='<li>'+inline(line.slice(2))+'</li>';}else if(/^#{1,6} /.test(line)){const n=line.indexOf(' ');html+=`<h${n}>${inline(line.slice(n+1))}</h${n}>`;}else if(line.startsWith('> ')){html+='<blockquote>'+inline(line.slice(2))+'</blockquote>';}else if(/^---+$/.test(line)){html+='<hr>';}else if(line.trim()){html+='<p>'+inline(line)+'</p>';}}if(list)html+='</ul>';if(code)html+='<pre>'+escapeHTML(codeLines.join('\n'))+'</pre>';return html;}
