function renderTech(){const q=$('tech-search').value.toLowerCase();$('tech-list').innerHTML=Object.keys(techs).filter(t=>t.toLowerCase().includes(q)).map(t=>`<button class="tech-chip ${state.tech.includes(t)?'selected':''}" data-tech="${t}" aria-pressed="${state.tech.includes(t)}">${state.tech.includes(t)?'✓ ': '+ '}${t}</button>`).join('')||'<p class="field-note">No matching technologies.</p>';$('tech-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{const t=b.dataset.tech;state.tech=state.tech.includes(t)?state.tech.filter(v=>v!==t):[...state.tech,t];renderTech();update();});}
