function decodeBase64UTF8(value){const bytes=Uint8Array.from(atob(value.replace(/\s/g,'')),c=>c.charCodeAt(0));return new TextDecoder().decode(bytes);}
async function github(path,signal){const res=await fetch('https://api.github.com/'+path,{headers:{Accept:'application/vnd.github+json'},signal});if(!res.ok){if(res.status===404)throw new Error('That GitHub profile was not found. Check the username.');if(res.status===403||res.status===429)throw new Error('GitHub’s public API limit was reached. Please try again later.');throw new Error('GitHub is unavailable right now. Please try again.');}return res.json();}
$('import-form').onsubmit=async e=>{e.preventDefault();const user=$('github-user').value.trim();if(!/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(user)){toast('Enter a valid GitHub username.');return;}importController?.abort();importController=new AbortController();const {signal}=importController;const timeout=setTimeout(()=>importController.abort(),20000);$('import-button').disabled=true;$('import-button').textContent='Importing…';$('import-message').textContent='';try{const profile=await github('users/'+encodeURIComponent(user),signal);const results=await Promise.allSettled([github(`users/${encodeURIComponent(user)}/repos?sort=updated&per_page=100`,signal),github(`repos/${encodeURIComponent(user)}/${encodeURIComponent(user)}/readme`,signal)]);const repos=results[0].status==='fulfilled'&&Array.isArray(results[0].value)?results[0].value.filter(r=>!r.fork).sort((a,b)=>b.stargazers_count-a.stargazers_count):null;const readme=results[1].status==='fulfilled'?results[1].value:null;state={...state,sourceMode:false,username:profile.login,name:profile.name||profile.login,headline:profile.bio||'',bio:'',location:profile.location||'',website:profile.blog||'',email:profile.email||'',working:'',learning:'',repos:repos?repos.slice(0,8).map(({name,html_url,description})=>({name,html_url,description})):[],custom:state.custom};if(repos){const languages=[...new Set(repos.map(r=>r.language).filter(l=>techs[l]))];state.tech=languages.slice(0,8);}importedReadme=readme?.content?decodeBase64UTF8(readme.content):'';state.sections.repos=!!state.repos.length;populate();$('import-message').replaceChildren(document.createTextNode(`✓ Imported @${profile.login}${repos===null?' · Repositories unavailable':''}. `));if(importedReadme){const btn=document.createElement('button');btn.type='button';btn.className='text-button';btn.textContent='Add existing README';btn.onclick=()=>{if(state.custom&&!confirm('Replace your additional Markdown with the imported README?'))return;state.custom=importedReadme;$('custom').value=state.custom;update();document.querySelector('[data-tab="extras"]').click();toast('Existing README added to Additional Markdown.');};$('import-message').append(btn);}toast('Welcome, '+(profile.name||profile.login)+'. Make yourself at home.');}catch(err){$('import-message').textContent=err.name==='AbortError'?'Import canceled or timed out. Please try again.':err.message;$('import-message').style.color='#b36544';}finally{clearTimeout(timeout);$('import-button').disabled=false;$('import-button').innerHTML='Import profile <span>↗</span>';}};
